mapper.select:
select inv.id as inventory_id, inv.sku_id, inv.warehouse_id, inv.quantity, min(h.create_time) as inbound_time, datediff(now(), min(h.create_time)) as overdue_days, sku.sku_name, item.item_name from wms_inventory inv inner join wms_inventory_history h on h.sku_id = inv.sku_id and h.warehouse_id = inv.warehouse_id and h.order_type = 1 and h.quantity > 0 left join wms_item_sku sku on sku.id = inv.sku_id left join wms_item item on item.id = sku.item_id where inv.quantity > 0
and inv.sku_id = #{skuId}
and inv.warehouse_id = #{fromWarehouseId}
group by inv.id, inv.sku_id, inv.warehouse_id, inv.quantity, sku.sku_name, item.item_name having datediff(now(), min(h.create_time)) >= #{thresholdDays} order by overdue_days desc
